    def to_dict_fn(self) -> StateFn:
        Returns:
            A new DictStateFn equivalent to ``self``.
        from .dict_state_fn import DictStateFn
        num_qubits = self.num_qubits
        new_dict = {format(i, 'b').zfill(num_qubits): v for i,
                    v in enumerate(self.primitive.data)}
        return DictStateFn(new_dict, coeff=self.coeff, is_measurement=self.is_measurement)
    def _expand_dim(self, num_qubits: int) -> 'VectorStateFn':
        primitive = np.zeros(2**num_qubits, dtype=complex)
        return VectorStateFn(self.primitive.tensor(primitive),
                             coeff=self.coeff,
                             is_measurement=self.is_measurement)
    def tensor(self, other: OperatorBase) -> OperatorBase:
        if isinstance(other, VectorStateFn):
            return StateFn(self.primitive.tensor(other.primitive),
                           coeff=self.coeff * other.coeff,
                           is_measurement=self.is_measurement)
        from .. import TensoredOp
        return TensoredOp([self, other])
    def to_density_matrix(self, massive: bool = False) -> np.ndarray:
        OperatorBase._check_massive(
            'to_density_matrix', True, self.num_qubits, massive)
        return self.primitive.to_operator().data * self.coeff
    def to_matrix(self, massive: bool = False) -> np.ndarray:
        OperatorBase._check_massive(
            'to_matrix', False, self.num_qubits, massive)
        vec = self.primitive.data * self.coeff
        return vec if not self.is_measurement else vec.reshape(1, -1)
    def to_matrix_op(self, massive: bool = False) -> OperatorBase:
        return self
    def to_circuit_op(self) -> OperatorBase:
        from .circuit_state_fn import CircuitStateFn
        csfn = CircuitStateFn.from_vector(
            self.primitive.data) * self.coeff
        return csfn.adjoint() if self.is_measurement else csfn
    def __str__(self) -> str:
        prim_str = str(self.primitive)
        if self.coeff == 1.0:
            return "{}({})".format('VectorStateFn' if not self.is_measurement
                                   else 'MeasurementVector', prim_str)
        else:
            return "{}({}) * {}".format('VectorStateFn' if not self.is_measurement
                                        else 'MeasurementVector',
                                        prim_str,
                                        self.coeff)
    def eval(self,
             front: Optional[Union[str, Dict[str, complex],
                                   np.ndarray, OperatorBase]] = None
             ) -> Union[OperatorBase, float, complex]:
        if front is None:
            return self
        if not self.is_measurement and isinstance(front, OperatorBase):
            raise ValueError(
                'Cannot compute overlap with StateFn or Operator if not Measurement. Try taking '
                'sf.adjoint() first to convert to measurement.')
        if isinstance(front, ListOp) and front.distributive:
            return front.combo_fn([self.eval(front.coeff * front_elem)
                                   for front_elem in front.oplist])
        if not isinstance(front, OperatorBase):
            front = StateFn(front)
        from ..operator_globals import EVAL_SIG_DIGITS
        from .operator_state_fn import OperatorStateFn
        from .circuit_state_fn import CircuitStateFn
        from .dict_state_fn import DictStateFn
        if isinstance(front, DictStateFn):
            return np.round(sum([v * self.primitive.data[int(b, 2)] * front.coeff
                                 for (b, v) in front.primitive.items()]) * self.coeff,
                            decimals=EVAL_SIG_DIGITS)
        if isinstance(front, VectorStateFn):
            return np.round(np.dot(self.to_matrix(), front.to_matrix())[0],
                            decimals=EVAL_SIG_DIGITS)
        if isinstance(front, CircuitStateFn):
            return np.conj(
                front.adjoint().eval(self.adjoint().primitive)) * self.coeff
        if isinstance(front, OperatorStateFn):
            return front.adjoint().eval(self.primitive) * self.coeff
        return front.adjoint().eval(self.adjoint().primitive).adjoint() * self.coeff
    def sample(self,
               shots: int = 1024,
               massive: bool = False,
               reverse_endianness: bool = False) -> dict:
        deterministic_counts = self.primitive.probabilities_dict()
        probs = np.array(list(deterministic_counts.values()))
        unique, counts = np.unique(aqua_globals.random.choice(list(deterministic_counts.keys()),
                                                              size=shots,
                                                              p=(probs / sum(probs))),
                                   return_counts=True)
        counts = dict(zip(unique, counts))
        if reverse_endianness:
            scaled_dict = {bstr[::-1]: (prob / shots)
                           for (bstr, prob) in counts.items()}
        else:
            scaled_dict = {bstr: (prob / shots)
                           for (bstr, prob) in counts.items()}
        return dict(sorted(scaled_dict.items(), key=lambda x: x[1], reverse=True))

