        self.add_move([[0, 1]], 1)
        self.add_move([[1, 0]], 0)
        self.add_move([[2, 0]], 1)
        self.add_move([[2, 2]], 0)
        self.add_move([[0, 0]], 1)
        self.add_move([[0, 2]], 0)
        self.add_move([[1, 1]], 1)
        self.add_move([[1, 2]], 0)

