    def get_rho(self):
        if self.y_boxes:
            corr = ['ZZ', 'ZX', 'XZ', 'XX', 'YY', 'YX', 'YZ', 'XY', 'ZY']
            ps = ['X', 'Y', 'Z']
        else:
            corr = ['ZZ', 'ZX', 'XZ', 'XX']
            ps = ['X', 'Z']
        self.rho = {}
        results = {}
        for basis in corr:
            temp_qc = copy.deepcopy(self.qc)
            for j in range(2):
                if basis[j] == 'X':
                    temp_qc.h(self.qr[j])
                elif basis[j] == 'Y':
                    temp_qc.sdg(self.qr[j])
                    temp_qc.h(self.qr[j])
            if self.backend == None:
                ket = Statevector([1, 0, 0, 0])
                ket = ket.from_instruction(temp_qc)
                results[basis] = ket.probabilities_dict()
            else:
                temp_qc.barrier(self.qr)
                temp_qc.measure(self.qr, self.cr)
                job = execute(temp_qc, backend=self.backend, shots=self.shots)
                results[basis] = job.result().get_counts()
                for string in results[basis]:
                    results[basis][string] = results[basis][string]/self.shots
        prob = {}
        for j in range(2):
            for p in ps:
                pauli = {}
                for pp in ['I']+ps:
                    pauli[pp] = (j == 1)*pp + p + (j == 0)*pp
                prob[pauli['I']] = 0
                for ppp in ps:
                    basis = pauli[ppp]
                    for string in results[basis]:
                        if string[(j+1) % 2] == '1':
                            prob[pauli['I']] += results[basis][string] / \
                                (2+self.y_boxes)
        for basis in corr:
            prob[basis] = 0
            for string in results[basis]:
                if string[0] != string[1]:
                    prob[basis] += results[basis][string]
        for pauli in prob:
            self.rho[pauli] = 1-2*prob[pauli]
    def update_grid(self, rho=None, labels=False, bloch=None, hidden=[], qubit=True, corr=True, message="", output=None):
        rho = None
            Dictionary of expectation values for 'ZI', 'IZ', 'ZZ', 'XI', 'IX', 'XX', 'ZX' and 'XZ'. If supplied, this will be visualized instead of the results of running self.qc.
        labels = False
            Determines whether basis labels are printed in the corresponding boxes.
        bloch = None
            If a qubit name is supplied, and if mode='line', Bloch circles are displayed for this qubit
        hidden = []
            Which qubits have their circles hidden (empty list if both shown).
        qubit = True
            Whether both circles shown for each qubit (use True for qubit puzzles and False for bit puzzles).
        corr = True
            Whether the correlation circles (the four in the middle) are shown.
        message
            A string of text that is displayed below the grid.
        def see_if_unhidden(pauli):
            unhidden = True
            for j in hidden:
                unhidden = unhidden and (pauli[j] == 'I')
            if qubit == False:
                for j in range(2):
                    unhidden = unhidden and (pauli[j] in ['I', 'Z'])
            if corr == False:
                unhidden = unhidden and (
                    (pauli[0] == 'I') or (pauli[1] == 'I'))
            unhidden = unhidden and (pauli in self.rho)
            return unhidden
        def add_line(line, pauli_pos, pauli):
            For mode='line', add in the line.
            line = the type of line to be drawn (X, Z or the other one)
            pauli = the box where the line is to be drawn
            expect = the expectation value that determines its length
            delta = 0.07
            unhidden = see_if_unhidden(pauli)
            p = (1-self.rho[pauli])/2
            if unhidden:
                if line == 'X':
                    a = (self.box[pauli_pos][0]-length/2,
                         self.box[pauli_pos][1]-width/2)
                    c = (self.box[pauli_pos][0]+length/2,
                         self.box[pauli_pos][1]-width/2)
                    b = (p*a[0] + (1-p)*c[0], p*a[1] + (1-p)*c[1])
                    self.ax.add_patch(
                        Rectangle(a, length*(1-p), width, angle=0, color=line_color[0]))
                    self.ax.add_patch(
                        Rectangle(b, length*p, width, angle=0, color=line_color[2]))
                    if length*p > delta:
                        self.ax.add_patch(Rectangle(
                            (b[0]+delta/2, b[1]+delta*0.6), length*p-delta, width-delta, angle=0, color=line_color[1]))
                elif line == 'Z':
                    a = (self.box[pauli_pos][0]-width/2,
                         self.box[pauli_pos][1]-length/2)
                    c = (self.box[pauli_pos][0]-width/2,
                         self.box[pauli_pos][1]+length/2)
                    b = (p*a[0] + (1-p)*c[0], p*a[1] + (1-p)*c[1])
                    self.ax.add_patch(
                        Rectangle(a, width, length*(1-p), angle=0, color=line_color[0]))
                    self.ax.add_patch(
                        Rectangle(b, width, length*p, angle=0, color=line_color[2]))
                    if length*p > delta:
                        self.ax.add_patch(Rectangle(
                            (b[0]+delta/2, b[1]+delta/2), width-delta, length*p-delta, angle=0, color=line_color[1]))
                else:
                    a = (self.box[pauli_pos][0]-length/(2*np.sqrt(2)),
                         self.box[pauli_pos][1]-length/(2*np.sqrt(2)))
                    c = (self.box[pauli_pos][0]+length/(2*np.sqrt(2)),
                         self.box[pauli_pos][1]+length/(2*np.sqrt(2)))
                    b = (p*a[0] + (1-p)*c[0], p*a[1] + (1-p)*c[1])
                    self.ax.add_patch(
                        Rectangle(a, width, length*(1-p), angle=-45, color=line_color[0]))
                    self.ax.add_patch(
                        Rectangle(b, width, length*p, angle=-45, color=line_color[2]))
                    if length*p > delta:
                        self.ax.add_patch(Rectangle((b[0]+delta*np.sqrt(2)/2, b[1]+delta*0.1*np.sqrt(
                            2)/2), width-delta, length*p-delta, angle=-45, color=line_color[1]))
            return p
        L = 0.98*np.sqrt(2)
        length = 0.75*L
        width = 0.12*L
        r = 0.6
        self.rho = rho
        if self.rho == {} or self.rho == None:
            self.get_rho()
        if self.initial:
            for pauli in self.box:
                if 'I' in pauli:
                    color = box_color[0]
                else:
                    color = box_color[1]
                self.ax.add_patch(Rectangle(
                    (self.box[pauli][0], self.box[pauli][1]-1), L, L, angle=45, color=color))
        for pauli in self.box:
            unhidden = see_if_unhidden(pauli)
            if unhidden:
                if self.mode != 'line':
                    prob = (1-self.rho[pauli])/2
                    color = (prob, prob, prob)
                    self.ax.add_patch(Circle(self.box[pauli], r, color=color))
                else:
                    if 'Y' in pauli:
                        self.ax.add_patch(
                            Circle(self.box[pauli], r, color=circle_color[1]))
                    else:
                        self.ax.add_patch(
                            Circle(self.box[pauli], r, color=circle_color[0]))
        for pauli in self.points:
            for point in self.points[pauli]:
                point.radius = 0
        if self.mode == 'line':
            if bloch in ['0', '1']:
                for other in 'IXZ':
                    px = other*(bloch == '1') + 'X' + other*(bloch == '0')
                    pz = other*(bloch == '1') + 'Z' + other*(bloch == '0')
                    prob_z = add_line('Z', pz, pz)
                    prob_x = add_line('X', pz, px)
                    for j, point in enumerate(self.points[pz]):
                        if see_if_unhidden(pz):
                            point.center = (
                                self.box[pz][0]-(prob_x-0.5)*length, self.box[pz][1]-(prob_z-0.5)*length)
                            point.radius = (j == 0)*0.05 + (j == 1)*0.04
                px = 'I'*(bloch == '0') + 'X' + 'I'*(bloch == '1')
                pz = 'I'*(bloch == '0') + 'Z' + 'I'*(bloch == '1')
                add_line('Z', pz, pz)
                add_line('X', px, px)
                if self.y_boxes:
                    for pauli in ['IY', 'YI', 'XY', 'YX', 'ZY', 'YZ', 'YY']:
                        add_line('ZXY', pauli, pauli)
