                    if pauli in ['XI', 'IX', 'XX']:
                        add_line('X', pauli, pauli)
                    if pauli in ['XZ', 'ZX']+self.y_boxes*['IY', 'YI', 'XY', 'YX', 'ZY', 'YZ', 'YY']:
                        add_line('ZXY', pauli, pauli)
        self.bottom.set_text(message)
        if labels:
